(x, y, t) => {
  const cx = 240, cy = 120;
  const masses = [
    [160+Math.sin(t*0.4)*120, 80+Math.cos(t*0.3)*60, 8000],
    [320+Math.cos(t*0.35)*100, 160+Math.sin(t*0.5)*80, 6000],
    [240+Math.sin(t*0.25+2)*140, 120+Math.cos(t*0.4+1)*100, 10000],
    [80+Math.cos(t*0.6+1)*60, 200+Math.sin(t*0.45+3)*50, 5000],
    [400+Math.sin(t*0.3+4)*80, 40+Math.cos(t*0.7+2)*60, 7000]
  ];
  let wx = 0, wy = 0;
  for (const [mx, my, m] of masses) {
    const dx = mx - x, dy = my - y;
    const d2 = dx*dx + dy*dy + 100;
    const force = m / d2;
    wx += dx * force * 0.008;
    wy += dy * force * 0.008;
  }
  wx += Math.sin(x*0.015+y*0.02+t*0.5)*10 + Math.cos(y*0.025-t*0.4)*7;
  wy += Math.cos(x*0.02-y*0.015+t*0.6)*10 + Math.sin(x*0.018+t*0.35)*7;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.12, 2.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.08, 2.0],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 3.0],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.15, 1.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.8],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.10, 2.2],
    [60+Math.sin(t*0.5+3)*70, 50+Math.cos(t*0.6+4)*40, 0.13, 1.6],
    [420+Math.cos(t*0.45+2)*60, 200+Math.sin(t*0.75+1)*50, 0.09, 2.4]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  const act = aS/src.length, inh = iS/src.length;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.9) + Math.sin(sx*0.028-sy*0.038+t*1.3))/2 + Math.sin((sx+sy)*0.11+t*2.8)*0.25 + Math.sin((sx-sy)*0.09-t*2.2)*0.25 + Math.sin(sx*0.06+t*1.5)*Math.cos(sy*0.05-t*1.2)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const potential = 1.0 / (1.0 + dist * 0.008);
  const kinetic = (Math.sin(dist*0.04-ang*4-t*1.8)*0.5+0.5);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*5-t*1.2))*0.35;
  const energy = potential * 0.6 + kinetic * 0.4;
  const cell2 = Math.sin(sx*0.18+Math.sin(sy*0.12+t)*2)*Math.sin(sy*0.16+Math.cos(sx*0.1+t)*2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.8)*0.3;
  const reaction = Math.tanh((act - inh*0.6 + bg*0.25 + spiral*0.3 + energy*0.2)*3.2);
  const blend = reaction*0.65 + cell*0.2 + cell2*0.15;
  const v = blend*0.5+0.5;
  const pal = [[2,2,8],[5,10,40],[10,50,120],[0,200,255],[0,255,140],[255,255,50],[255,100,200],[255,50,50],[180,30,255],[40,10,80],[2,2,8]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const glow = Math.pow(Math.max(0, reaction), 2)*1.4;
  const edge = Math.abs(reaction)>0.6?1.0+glow:1.0;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const eS = energy*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*40*eS)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*70*eS)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*130*eS)|0
  ];
}
